bool ExternalModManager::TryParseMaterialDefinitions(const std::string& content, int32_t apiVersion,
                                                     std::vector<ExternalModMaterialDefinition>& outDefinitions,
                                                     std::string& outError) {
    outDefinitions.clear();
    if (apiVersion < kExternalModApiVersionV4) {
        outError = "materialDefinitions requires apiVersion 4";
        return false;
    }

    nlohmann::json json;
    try {
        json = nlohmann::json::parse(content);
    } catch (const std::exception& ex) {
        outError = std::string("materials.json parse error: ") + ex.what();
        return false;
    }

    if (!json.is_object() || !json.contains("schemaVersion") || !json["schemaVersion"].is_number_integer() ||
        json["schemaVersion"].get<int32_t>() != 1) {
        outError = "materials.json schemaVersion must be 1";
        return false;
    }
    if (!json.contains("materials") || !json["materials"].is_array()) {
        outError = "materials.json must contain materials[]";
        return false;
    }

    std::unordered_set<std::string> seenIds;
    for (size_t i = 0; i < json["materials"].size(); ++i) {
        const auto& material = json["materials"][i];
        if (!material.is_object()) {
            outError = "materials[" + std::to_string(i) + "] must be object";
            return false;
        }

        ExternalModMaterialDefinition definition;
        if (!ValidateRequiredString(material, "id", definition.id, outError)) {
            outError = "materials[" + std::to_string(i) + "].id: " + outError;
            return false;
        }
        if (!IsNamespacedCatalogId(definition.id)) {
            outError = "materials[" + std::to_string(i) + "].id must be namespaced";
            return false;
        }
        if (!seenIds.insert(definition.id).second) {
            outError = "Duplicate material id: " + definition.id;
            return false;
        }

        if (material.contains("bindOtrPath")) {
            if (!material["bindOtrPath"].is_string()) {
                outError = "materials[" + std::to_string(i) + "].bindOtrPath must be string";
                return false;
            }
            definition.bindOtrPath = material["bindOtrPath"].get<std::string>();
        }
        if (material.contains("binds")) {
            if (!material["binds"].is_array()) {
                outError = "materials[" + std::to_string(i) + "].binds must be array";
                return false;
            }
            for (size_t bindIndex = 0; bindIndex < material["binds"].size(); ++bindIndex) {
                const auto& bind = material["binds"][bindIndex];
                if (!bind.is_object()) {
                    outError = "materials[" + std::to_string(i) + "].binds[" + std::to_string(bindIndex) +
                               "] must be object";
                    return false;
                }
                ExternalModMaterialDefinition::Bind bindDefinition;
                if (!ValidateRequiredString(bind, "otrPath", bindDefinition.otrPath, outError)) {
                    outError = "materials[" + std::to_string(i) + "].binds[" + std::to_string(bindIndex) +
                               "].otrPath: " + outError;
                    return false;
                }
                if (bind.contains("sceneId")) {
                    if (!bind["sceneId"].is_number_integer()) {
                        outError = "materials[" + std::to_string(i) + "].binds[" + std::to_string(bindIndex) +
                                   "].sceneId must be integer";
                        return false;
                    }
                    bindDefinition.sceneId = static_cast<int16_t>(bind["sceneId"].get<int32_t>());
                    bindDefinition.hasSceneId = true;
                }
                if (bind.contains("roomId")) {
                    if (!bind["roomId"].is_number_integer()) {
                        outError = "materials[" + std::to_string(i) + "].binds[" + std::to_string(bindIndex) +
                                   "].roomId must be integer";
                        return false;
                    }
                    bindDefinition.roomId = static_cast<int16_t>(bind["roomId"].get<int32_t>());
                    bindDefinition.hasRoomId = true;
                }
                definition.binds.push_back(std::move(bindDefinition));
            }
        }
        if (material.contains("maps")) {
            if (!material["maps"].is_object()) {
                outError = "materials[" + std::to_string(i) + "].maps must be object";
                return false;
            }
            const auto& maps = material["maps"];
            auto parseMapPath = [&](const char* fieldName, std::string& outPath) -> bool {
                if (!maps.contains(fieldName)) {
                    return true;
                }
                if (!maps[fieldName].is_string()) {
                    outError = "materials[" + std::to_string(i) + "].maps." + fieldName + " must be string";
                    return false;
                }
                outPath = maps[fieldName].get<std::string>();
                return true;
            };
            if (!parseMapPath("albedo", definition.mapAlbedoAsset) ||
                !parseMapPath("normal", definition.mapNormalAsset) ||
                !parseMapPath("orm", definition.mapOrmAsset) ||
                !parseMapPath("height", definition.mapHeightAsset) ||
                !parseMapPath("emissive", definition.mapEmissiveAsset)) {
                return false;
            }
        }
        if (material.contains("shadingModel")) {
            if (!material["shadingModel"].is_string()) {
                outError = "materials[" + std::to_string(i) + "].shadingModel must be string";
                return false;
            }
            definition.shadingModel = ToLower(material["shadingModel"].get<std::string>());
        }
        if (material.contains("normalScale")) {
            if (!material["normalScale"].is_number()) {
                outError = "materials[" + std::to_string(i) + "].normalScale must be numeric";
                return false;
            }
            definition.normalScale = std::clamp(material["normalScale"].get<float>(), 0.0f, 8.0f);
        }
        if (material.contains("emissiveIntensity")) {
            if (!material["emissiveIntensity"].is_number()) {
                outError = "materials[" + std::to_string(i) + "].emissiveIntensity must be numeric";
                return false;
            }
            definition.emissiveIntensity = std::clamp(material["emissiveIntensity"].get<float>(), 0.0f, 32.0f);
        }
        if (material.contains("parallaxScale")) {
            if (!material["parallaxScale"].is_number()) {
                outError = "materials[" + std::to_string(i) + "].parallaxScale must be numeric";
                return false;
            }
            definition.parallaxScale = std::clamp(material["parallaxScale"].get<float>(), 0.0f, 0.2f);
        }
        if (material.contains("params")) {
            if (!material["params"].is_object()) {
                outError = "materials[" + std::to_string(i) + "].params must be object";
                return false;
            }
            const auto& params = material["params"];
            if (params.contains("normalScale")) {
                if (!params["normalScale"].is_number()) {
                    outError = "materials[" + std::to_string(i) + "].params.normalScale must be numeric";
                    return false;
                }
                definition.normalScale = std::clamp(params["normalScale"].get<float>(), 0.0f, 8.0f);
            }
            if (params.contains("emissiveIntensity")) {
                if (!params["emissiveIntensity"].is_number()) {
                    outError = "materials[" + std::to_string(i) + "].params.emissiveIntensity must be numeric";
                    return false;
                }
                definition.emissiveIntensity = std::clamp(params["emissiveIntensity"].get<float>(), 0.0f, 32.0f);
            }
            if (params.contains("alphaMode")) {
                if (!params["alphaMode"].is_string()) {
                    outError = "materials[" + std::to_string(i) + "].params.alphaMode must be string";
                    return false;
                }
                definition.alphaMode = ToLower(params["alphaMode"].get<std::string>());
            }
            if (params.contains("parallax")) {
                if (!params["parallax"].is_object()) {
                    outError = "materials[" + std::to_string(i) + "].params.parallax must be object";
                    return false;
                }
                const auto& parallax = params["parallax"];
                if (parallax.contains("scale")) {
                    if (!parallax["scale"].is_number()) {
                        outError = "materials[" + std::to_string(i) + "].params.parallax.scale must be numeric";
                        return false;
                    }
                    definition.parallaxScale = std::clamp(parallax["scale"].get<float>(), 0.0f, 0.2f);
                }
                if (parallax.contains("steps")) {
                    if (!parallax["steps"].is_number_integer()) {
                        outError = "materials[" + std::to_string(i) + "].params.parallax.steps must be integer";
                        return false;
                    }
                    definition.parallaxSteps = std::clamp(parallax["steps"].get<int32_t>(), 1, 64);
                }
                if (parallax.contains("mode")) {
                    if (!parallax["mode"].is_string()) {
                        outError = "materials[" + std::to_string(i) + "].params.parallax.mode must be string";
                        return false;
                    }
                    definition.parallaxMode = ToLower(parallax["mode"].get<std::string>());
                }
            }
        }
        if (material.contains("alphaMode")) {
            if (!material["alphaMode"].is_string()) {
                outError = "materials[" + std::to_string(i) + "].alphaMode must be string";
                return false;
            }
            definition.alphaMode = ToLower(material["alphaMode"].get<std::string>());
        }

        outDefinitions.push_back(std::move(definition));
    }

    return true;
}

bool ExternalModManager::TryParsePbrDefinitions(const std::string& content, int32_t apiVersion,
                                                std::vector<ExternalModPbrDefinition>& outDefinitions,
                                                std::string& outError) {
    outDefinitions.clear();
    if (apiVersion < kExternalModApiVersionV4) {
        outError = "pbrDefinitions requires apiVersion 4";
        return false;
    }

    nlohmann::json json;
    try {
        json = nlohmann::json::parse(content);
    } catch (const std::exception& ex) {
        outError = std::string("pbr_profiles.json parse error: ") + ex.what();
        return false;
    }

    if (!json.is_object() || !json.contains("schemaVersion") || !json["schemaVersion"].is_number_integer() ||
        json["schemaVersion"].get<int32_t>() != 1) {
        outError = "pbr_profiles.json schemaVersion must be 1";
        return false;
    }
    if (!json.contains("profiles") || !json["profiles"].is_array()) {
        outError = "pbr_profiles.json must contain profiles[]";
        return false;
    }

    std::unordered_set<std::string> seenIds;
    for (size_t i = 0; i < json["profiles"].size(); ++i) {
        const auto& profile = json["profiles"][i];
        if (!profile.is_object()) {
            outError = "profiles[" + std::to_string(i) + "] must be object";
            return false;
        }

        ExternalModPbrDefinition definition;
        if (!ValidateRequiredString(profile, "id", definition.id, outError)) {
            outError = "profiles[" + std::to_string(i) + "].id: " + outError;
            return false;
        }
        if (!IsNamespacedCatalogId(definition.id)) {
            outError = "profiles[" + std::to_string(i) + "].id must be namespaced";
            return false;
        }
        if (!seenIds.insert(definition.id).second) {
            outError = "Duplicate pbr profile id: " + definition.id;
            return false;
        }

        if (profile.contains("enabled")) {
            if (!profile["enabled"].is_boolean()) {
                outError = "profiles[" + std::to_string(i) + "].enabled must be boolean";
                return false;
            }
            definition.enabled = profile["enabled"].get<bool>();
        }
        if (profile.contains("enablePom")) {
            if (!profile["enablePom"].is_boolean()) {
                outError = "profiles[" + std::to_string(i) + "].enablePom must be boolean";
                return false;
            }
            definition.enablePom = profile["enablePom"].get<bool>();
        }
        if (profile.contains("pomSteps")) {
            if (!profile["pomSteps"].is_number_integer()) {
                outError = "profiles[" + std::to_string(i) + "].pomSteps must be integer";
                return false;
            }
            definition.pomSteps = std::clamp(profile["pomSteps"].get<int32_t>(), 1, 64);
        }
        if (profile.contains("pomMaxDistance")) {
            if (!profile["pomMaxDistance"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].pomMaxDistance must be numeric";
                return false;
            }
            definition.pomMaxDistance = std::clamp(profile["pomMaxDistance"].get<float>(), 0.0f, 10000.0f);
        }
        if (profile.contains("maxDynamicLightsNear")) {
            if (!profile["maxDynamicLightsNear"].is_number_integer()) {
                outError = "profiles[" + std::to_string(i) + "].maxDynamicLightsNear must be integer";
                return false;
            }
            definition.maxDynamicLightsNear = std::clamp(profile["maxDynamicLightsNear"].get<int32_t>(), 1, 256);
        }
        if (profile.contains("maxDynamicLightsTotal")) {
            if (!profile["maxDynamicLightsTotal"].is_number_integer()) {
                outError = "profiles[" + std::to_string(i) + "].maxDynamicLightsTotal must be integer";
                return false;
            }
            definition.maxDynamicLightsTotal = std::clamp(profile["maxDynamicLightsTotal"].get<int32_t>(), 1, 1024);
        }
        if (profile.contains("backendPolicy")) {
            if (!profile["backendPolicy"].is_string()) {
                outError = "profiles[" + std::to_string(i) + "].backendPolicy must be string";
                return false;
            }
            definition.backendPolicy = ToLower(profile["backendPolicy"].get<std::string>());
        }
        if (profile.contains("ambientOcclusion")) {
            if (!profile["ambientOcclusion"].is_object()) {
                outError = "profiles[" + std::to_string(i) + "].ambientOcclusion must be object";
                return false;
            }
            const auto& ao = profile["ambientOcclusion"];
            if (ao.contains("enabled")) {
                if (!ao["enabled"].is_boolean()) {
                    outError = "profiles[" + std::to_string(i) + "].ambientOcclusion.enabled must be boolean";
                    return false;
                }
                definition.ambientOcclusion.enabled = ao["enabled"].get<bool>();
            }
            if (ao.contains("quality")) {
                if (!ao["quality"].is_string()) {
                    outError = "profiles[" + std::to_string(i) + "].ambientOcclusion.quality must be string";
                    return false;
                }
                definition.ambientOcclusion.quality = ToLower(ao["quality"].get<std::string>());
                if (definition.ambientOcclusion.quality != "low" && definition.ambientOcclusion.quality != "medium" &&
                    definition.ambientOcclusion.quality != "high") {
                    outError = "profiles[" + std::to_string(i) + "].ambientOcclusion.quality must be low|medium|high";
                    return false;
                }
            }
            if (ao.contains("radius")) {
                if (!ao["radius"].is_number()) {
                    outError = "profiles[" + std::to_string(i) + "].ambientOcclusion.radius must be numeric";
                    return false;
                }
                definition.ambientOcclusion.radius = std::clamp(ao["radius"].get<float>(), 0.05f, 3.0f);
            }
            if (ao.contains("intensity")) {
                if (!ao["intensity"].is_number()) {
                    outError = "profiles[" + std::to_string(i) + "].ambientOcclusion.intensity must be numeric";
                    return false;
                }
                definition.ambientOcclusion.intensity = std::clamp(ao["intensity"].get<float>(), 0.0f, 3.0f);
            }
            if (ao.contains("bias")) {
                if (!ao["bias"].is_number()) {
                    outError = "profiles[" + std::to_string(i) + "].ambientOcclusion.bias must be numeric";
                    return false;
                }
                definition.ambientOcclusion.bias = std::clamp(ao["bias"].get<float>(), 0.0f, 0.2f);
            }
            if (ao.contains("power")) {
                if (!ao["power"].is_number()) {
                    outError = "profiles[" + std::to_string(i) + "].ambientOcclusion.power must be numeric";
                    return false;
                }
                definition.ambientOcclusion.power = std::clamp(ao["power"].get<float>(), 0.1f, 4.0f);
            }
            if (ao.contains("maxDistance")) {
                if (!ao["maxDistance"].is_number()) {
                    outError = "profiles[" + std::to_string(i) + "].ambientOcclusion.maxDistance must be numeric";
                    return false;
                }
                definition.ambientOcclusion.maxDistance = std::clamp(ao["maxDistance"].get<float>(), 50.0f, 5000.0f);
            }
            if (ao.contains("blurPasses")) {
                if (!ao["blurPasses"].is_number_integer()) {
                    outError = "profiles[" + std::to_string(i) + "].ambientOcclusion.blurPasses must be integer";
                    return false;
                }
                definition.ambientOcclusion.blurPasses = std::clamp(ao["blurPasses"].get<int32_t>(), 0, 4);
            }
        }

        outDefinitions.push_back(std::move(definition));
    }

    return true;
}

bool ExternalModManager::TryParseLightingDefinitions(const std::string& content, int32_t apiVersion,
                                                     std::vector<ExternalModLightProfileDefinition>& outDefinitions,
                                                     std::string& outError) {
    outDefinitions.clear();
    if (apiVersion < kExternalModApiVersionV4) {
        outError = "lightingDefinitions requires apiVersion 4";
        return false;
    }

    nlohmann::json json;
    try {
        json = nlohmann::json::parse(content);
    } catch (const std::exception& ex) {
        outError = std::string("light_profiles.json parse error: ") + ex.what();
        return false;
    }

    if (!json.is_object() || !json.contains("schemaVersion") || !json["schemaVersion"].is_number_integer() ||
        json["schemaVersion"].get<int32_t>() != 1) {
        outError = "light_profiles.json schemaVersion must be 1";
        return false;
    }
    if (!json.contains("profiles") || !json["profiles"].is_array()) {
        outError = "light_profiles.json must contain profiles[]";
        return false;
    }

    std::unordered_set<std::string> seenIds;
    for (size_t i = 0; i < json["profiles"].size(); ++i) {
        const auto& profile = json["profiles"][i];
        if (!profile.is_object()) {
            outError = "profiles[" + std::to_string(i) + "] must be object";
            return false;
        }

        ExternalModLightProfileDefinition definition;
        if (!ValidateRequiredString(profile, "id", definition.id, outError)) {
            outError = "profiles[" + std::to_string(i) + "].id: " + outError;
            return false;
        }
        if (!IsNamespacedCatalogId(definition.id)) {
            outError = "profiles[" + std::to_string(i) + "].id must be namespaced";
            return false;
        }
        if (!seenIds.insert(definition.id).second) {
            outError = "Duplicate light profile id: " + definition.id;
            return false;
        }

        if (profile.contains("type")) {
            if (!profile["type"].is_string()) {
                outError = "profiles[" + std::to_string(i) + "].type must be string";
                return false;
            }
            definition.lightType = ToLower(profile["type"].get<std::string>());
        }
        if (profile.contains("color")) {
            if (!profile["color"].is_array() || profile["color"].size() != 3 ||
                !profile["color"][0].is_number() || !profile["color"][1].is_number() || !profile["color"][2].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].color must be [r,g,b] numeric";
                return false;
            }
            definition.colorLinear = { {
                std::clamp(profile["color"][0].get<float>(), 0.0f, 16.0f),
                std::clamp(profile["color"][1].get<float>(), 0.0f, 16.0f),
                std::clamp(profile["color"][2].get<float>(), 0.0f, 16.0f),
            } };
        }
        if (profile.contains("kelvin")) {
            if (!profile["kelvin"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].kelvin must be numeric";
                return false;
            }
            definition.kelvin = std::clamp(profile["kelvin"].get<float>(), 1000.0f, 40000.0f);
            definition.hasKelvin = true;
        }
        if (profile.contains("intensity")) {
            if (!profile["intensity"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].intensity must be numeric";
                return false;
            }
            definition.intensity = std::clamp(profile["intensity"].get<float>(), 0.0f, 50000.0f);
        }
        if (profile.contains("radius")) {
            if (!profile["radius"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].radius must be numeric";
                return false;
            }
            definition.radius = std::clamp(profile["radius"].get<float>(), 0.0f, 10000.0f);
        }
        if (profile.contains("falloff")) {
            if (!profile["falloff"].is_string()) {
                outError = "profiles[" + std::to_string(i) + "].falloff must be string";
                return false;
            }
            definition.falloff = ToLower(profile["falloff"].get<std::string>());
        }
        if (profile.contains("innerConeDeg")) {
            if (!profile["innerConeDeg"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].innerConeDeg must be numeric";
                return false;
            }
            definition.innerConeDeg = std::clamp(profile["innerConeDeg"].get<float>(), 0.0f, 180.0f);
        }
        if (profile.contains("outerConeDeg")) {
            if (!profile["outerConeDeg"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].outerConeDeg must be numeric";
                return false;
            }
            definition.outerConeDeg = std::clamp(profile["outerConeDeg"].get<float>(), 0.0f, 180.0f);
        }
        if (profile.contains("direction")) {
            if (!profile["direction"].is_array() || profile["direction"].size() != 3 || !profile["direction"][0].is_number() ||
                !profile["direction"][1].is_number() || !profile["direction"][2].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].direction must be [x,y,z] numeric";
                return false;
            }
            definition.direction = { {
                std::clamp(profile["direction"][0].get<float>(), -1.0f, 1.0f),
                std::clamp(profile["direction"][1].get<float>(), -1.0f, 1.0f),
                std::clamp(profile["direction"][2].get<float>(), -1.0f, 1.0f),
            } };
        }
        if (profile.contains("flicker")) {
            if (!profile["flicker"].is_boolean()) {
                outError = "profiles[" + std::to_string(i) + "].flicker must be boolean";
                return false;
            }
            definition.flicker = profile["flicker"].get<bool>();
        }
        if (profile.contains("flickerAmount")) {
            if (!profile["flickerAmount"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].flickerAmount must be numeric";
                return false;
            }
            definition.flickerAmount = std::clamp(profile["flickerAmount"].get<float>(), 0.0f, 1.0f);
        }
        if (profile.contains("defaultLifetimeMs")) {
            if (!profile["defaultLifetimeMs"].is_number_integer()) {
                outError = "profiles[" + std::to_string(i) + "].defaultLifetimeMs must be integer";
                return false;
            }
            definition.defaultLifetimeMs = std::clamp(profile["defaultLifetimeMs"].get<int32_t>(), 0, 600000);
        }
        if (profile.contains("castShadows")) {
            if (!profile["castShadows"].is_boolean()) {
                outError = "profiles[" + std::to_string(i) + "].castShadows must be boolean";
                return false;
            }
            definition.castShadows = profile["castShadows"].get<bool>();
        }
        if (profile.contains("shadowResolution")) {
            if (!profile["shadowResolution"].is_number_integer()) {
                outError = "profiles[" + std::to_string(i) + "].shadowResolution must be integer";
                return false;
            }
            definition.shadowResolution = std::clamp(profile["shadowResolution"].get<int32_t>(), 64, 4096);
        }
        if (profile.contains("shadowBias")) {
            if (!profile["shadowBias"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].shadowBias must be numeric";
                return false;
            }
            definition.shadowBias = std::clamp(profile["shadowBias"].get<float>(), 0.0f, 1.0f);
        }
        if (profile.contains("shadowNormalBias")) {
            if (!profile["shadowNormalBias"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].shadowNormalBias must be numeric";
                return false;
            }
            definition.shadowNormalBias = std::clamp(profile["shadowNormalBias"].get<float>(), 0.0f, 2.0f);
        }
        if (profile.contains("shadowRange")) {
            if (!profile["shadowRange"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].shadowRange must be numeric";
                return false;
            }
            definition.shadowRange = std::clamp(profile["shadowRange"].get<float>(), 0.0f, 20000.0f);
        }
        if (profile.contains("volumetricIntensity")) {
            if (!profile["volumetricIntensity"].is_number()) {
                outError = "profiles[" + std::to_string(i) + "].volumetricIntensity must be numeric";
                return false;
            }
            definition.volumetricIntensity = std::clamp(profile["volumetricIntensity"].get<float>(), 0.0f, 8.0f);
        }

        outDefinitions.push_back(std::move(definition));
    }

    return true;
}

bool ExternalModManager::TryParsePostFxDefinitions(const std::string& content, int32_t apiVersion,
                                                   std::vector<ExternalModPostFxPresetDefinition>& outDefinitions,
                                                   std::string& outError) {
    outDefinitions.clear();
    if (apiVersion < kExternalModApiVersionV4) {
        outError = "postFxDefinitions requires apiVersion 4";
        return false;
    }

    nlohmann::json json;
    try {
        json = nlohmann::json::parse(content);
    } catch (const std::exception& ex) {
        outError = std::string("postfx_presets.json parse error: ") + ex.what();
        return false;
    }

    if (!json.is_object() || !json.contains("schemaVersion") || !json["schemaVersion"].is_number_integer() ||
        json["schemaVersion"].get<int32_t>() != 1) {
        outError = "postfx_presets.json schemaVersion must be 1";
        return false;
    }
    if (!json.contains("presets") || !json["presets"].is_array()) {
        outError = "postfx_presets.json must contain presets[]";
        return false;
    }

    std::unordered_set<std::string> seenIds;
    for (size_t i = 0; i < json["presets"].size(); ++i) {
        const auto& preset = json["presets"][i];
        if (!preset.is_object()) {
            outError = "presets[" + std::to_string(i) + "] must be object";
            return false;
        }

        ExternalModPostFxPresetDefinition definition;
        if (!ValidateRequiredString(preset, "id", definition.id, outError)) {
            outError = "presets[" + std::to_string(i) + "].id: " + outError;
            return false;
        }
        if (!IsNamespacedCatalogId(definition.id)) {
            outError = "presets[" + std::to_string(i) + "].id must be namespaced";
            return false;
        }
        if (!seenIds.insert(definition.id).second) {
            outError = "Duplicate postfx preset id: " + definition.id;
            return false;
        }

        if (preset.contains("tonemap")) {
            if (!preset["tonemap"].is_string()) {
                outError = "presets[" + std::to_string(i) + "].tonemap must be string";
                return false;
            }
            definition.tonemap = ToLower(preset["tonemap"].get<std::string>());
        }
        if (preset.contains("exposure")) {
            if (!preset["exposure"].is_number()) {
                outError = "presets[" + std::to_string(i) + "].exposure must be numeric";
                return false;
            }
            definition.exposure = std::clamp(preset["exposure"].get<float>(), 0.0f, 8.0f);
        }
        if (preset.contains("bloom")) {
            if (!preset["bloom"].is_number()) {
                outError = "presets[" + std::to_string(i) + "].bloom must be numeric";
                return false;
            }
            definition.bloom = std::clamp(preset["bloom"].get<float>(), 0.0f, 10.0f);
        }
        if (preset.contains("fogColor")) {
            if (!preset["fogColor"].is_array() || preset["fogColor"].size() != 4) {
                outError = "presets[" + std::to_string(i) + "].fogColor must be [r,g,b,a]";
                return false;
            }
            for (size_t c = 0; c < 4; ++c) {
                if (!preset["fogColor"][c].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].fogColor must be numeric";
                    return false;
                }
                definition.fogColor[c] = std::clamp(preset["fogColor"][c].get<float>(), 0.0f, 1.0f);
            }
        }
        if (preset.contains("fogDensity")) {
            if (!preset["fogDensity"].is_number()) {
                outError = "presets[" + std::to_string(i) + "].fogDensity must be numeric";
                return false;
            }
            definition.fogDensity = std::clamp(preset["fogDensity"].get<float>(), 0.0f, 1.0f);
        }
        if (preset.contains("fogNear")) {
            if (!preset["fogNear"].is_number_integer()) {
                outError = "presets[" + std::to_string(i) + "].fogNear must be integer";
                return false;
            }
            definition.fogNear = std::clamp(preset["fogNear"].get<int32_t>(), 0, 1000);
            definition.hasFogNear = true;
        }
        if (preset.contains("fogFar")) {
            if (!preset["fogFar"].is_number_integer()) {
                outError = "presets[" + std::to_string(i) + "].fogFar must be integer";
                return false;
            }
            definition.fogFar = std::clamp(preset["fogFar"].get<int32_t>(), 0, 1000);
            definition.hasFogFar = true;
        }
        if (preset.contains("vignette")) {
            if (!preset["vignette"].is_number()) {
                outError = "presets[" + std::to_string(i) + "].vignette must be numeric";
                return false;
            }
            definition.vignette = std::clamp(preset["vignette"].get<float>(), 0.0f, 1.0f);
        }
        if (preset.contains("saturation")) {
            if (!preset["saturation"].is_number()) {
                outError = "presets[" + std::to_string(i) + "].saturation must be numeric";
                return false;
            }
            definition.saturation = std::clamp(preset["saturation"].get<float>(), 0.0f, 2.5f);
        }
        if (preset.contains("forceFogOverlay")) {
            if (!preset["forceFogOverlay"].is_boolean()) {
                outError = "presets[" + std::to_string(i) + "].forceFogOverlay must be boolean";
                return false;
            }
            definition.forceFogOverlay = preset["forceFogOverlay"].get<bool>();
        }
        if (preset.contains("fogOverlayStrength")) {
            if (!preset["fogOverlayStrength"].is_number()) {
                outError = "presets[" + std::to_string(i) + "].fogOverlayStrength must be numeric";
                return false;
            }
            definition.fogOverlayStrength = std::clamp(preset["fogOverlayStrength"].get<float>(), 0.0f, 1.0f);
        }
        if (preset.contains("forceDepthAwareFog")) {
            if (!preset["forceDepthAwareFog"].is_boolean()) {
                outError = "presets[" + std::to_string(i) + "].forceDepthAwareFog must be boolean";
                return false;
            }
            definition.forceDepthAwareFog = preset["forceDepthAwareFog"].get<bool>();
        }
        if (preset.contains("volumetrics")) {
            if (!preset["volumetrics"].is_object()) {
                outError = "presets[" + std::to_string(i) + "].volumetrics must be object";
                return false;
            }
            const auto& volumetrics = preset["volumetrics"];
            definition.hasVolumetrics = true;
            if (volumetrics.contains("enabled")) {
                if (!volumetrics["enabled"].is_boolean()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.enabled must be boolean";
                    return false;
                }
                definition.volumetrics.enabled = volumetrics["enabled"].get<bool>();
            }
            if (volumetrics.contains("quality")) {
                if (!volumetrics["quality"].is_string()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.quality must be string";
                    return false;
                }
                definition.volumetrics.quality = ToLower(volumetrics["quality"].get<std::string>());
            }
            if (volumetrics.contains("density")) {
                if (!volumetrics["density"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.density must be numeric";
                    return false;
                }
                definition.volumetrics.density = std::clamp(volumetrics["density"].get<float>(), 0.0f, 2.0f);
            }
            if (volumetrics.contains("color")) {
                if (!volumetrics["color"].is_array() || volumetrics["color"].size() != definition.volumetrics.color.size()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.color must be [r,g,b]";
                    return false;
                }
                for (size_t colorIndex = 0; colorIndex < definition.volumetrics.color.size(); ++colorIndex) {
                    const auto& colorValue = volumetrics["color"][colorIndex];
                    if (!colorValue.is_number()) {
                        outError = "presets[" + std::to_string(i) + "].volumetrics.color[" + std::to_string(colorIndex) +
                                   "] must be numeric";
                        return false;
                    }
                    definition.volumetrics.color[colorIndex] = std::clamp(colorValue.get<float>(), 0.0f, 16.0f);
                }
                definition.volumetrics.hasColor = true;
            }
            if (volumetrics.contains("ambientIntensity")) {
                if (!volumetrics["ambientIntensity"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.ambientIntensity must be numeric";
                    return false;
                }
                definition.volumetrics.ambientIntensity =
                    std::clamp(volumetrics["ambientIntensity"].get<float>(), 0.0f, 8.0f);
            }
            if (volumetrics.contains("anisotropy")) {
                if (!volumetrics["anisotropy"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.anisotropy must be numeric";
                    return false;
                }
                definition.volumetrics.anisotropy = std::clamp(volumetrics["anisotropy"].get<float>(), -0.95f, 0.95f);
            }
            if (volumetrics.contains("startDistance")) {
                if (!volumetrics["startDistance"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.startDistance must be numeric";
                    return false;
                }
                definition.volumetrics.startDistance =
                    std::clamp(volumetrics["startDistance"].get<float>(), 0.0f, 4000.0f);
            }
            if (volumetrics.contains("maxDistance")) {
                if (!volumetrics["maxDistance"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.maxDistance must be numeric";
                    return false;
                }
                definition.volumetrics.maxDistance =
                    std::clamp(volumetrics["maxDistance"].get<float>(), 1.0f, 20000.0f);
            }
            if (volumetrics.contains("heightFogEnabled")) {
                if (!volumetrics["heightFogEnabled"].is_boolean()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.heightFogEnabled must be boolean";
                    return false;
                }
                definition.volumetrics.heightFogEnabled = volumetrics["heightFogEnabled"].get<bool>();
            }
            if (volumetrics.contains("baseHeight")) {
                if (!volumetrics["baseHeight"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.baseHeight must be numeric";
                    return false;
                }
                definition.volumetrics.baseHeight =
                    std::clamp(volumetrics["baseHeight"].get<float>(), -20000.0f, 20000.0f);
            }
            if (volumetrics.contains("heightFalloff")) {
                if (!volumetrics["heightFalloff"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.heightFalloff must be numeric";
                    return false;
                }
                definition.volumetrics.heightFalloff =
                    std::clamp(volumetrics["heightFalloff"].get<float>(), 0.0f, 0.05f);
            }
            if (volumetrics.contains("lightShaftIntensity")) {
                if (!volumetrics["lightShaftIntensity"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.lightShaftIntensity must be numeric";
                    return false;
                }
                definition.volumetrics.lightShaftIntensity =
                    std::clamp(volumetrics["lightShaftIntensity"].get<float>(), 0.0f, 8.0f);
            }
            if (volumetrics.contains("shadowIntensity")) {
                if (!volumetrics["shadowIntensity"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.shadowIntensity must be numeric";
                    return false;
                }
                definition.volumetrics.shadowIntensity =
                    std::clamp(volumetrics["shadowIntensity"].get<float>(), 0.0f, 1.0f);
            }
            if (volumetrics.contains("temporalBlend")) {
                if (!volumetrics["temporalBlend"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.temporalBlend must be numeric";
                    return false;
                }
                definition.volumetrics.temporalBlend =
                    std::clamp(volumetrics["temporalBlend"].get<float>(), 0.0f, 0.99f);
            }
            if (volumetrics.contains("jitterScale")) {
                if (!volumetrics["jitterScale"].is_number()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.jitterScale must be numeric";
                    return false;
                }
                definition.volumetrics.jitterScale = std::clamp(volumetrics["jitterScale"].get<float>(), 0.0f, 4.0f);
            }
            if (volumetrics.contains("debugView")) {
                if (!volumetrics["debugView"].is_boolean()) {
                    outError = "presets[" + std::to_string(i) + "].volumetrics.debugView must be boolean";
                    return false;
                }
                definition.volumetrics.debugView = volumetrics["debugView"].get<bool>();
            }
        }

        outDefinitions.push_back(std::move(definition));
    }

    return true;
}

bool ExternalModManager::TryParseSceneProfileDefinitions(const std::string& content, int32_t apiVersion,
                                                         std::vector<ExternalModSceneProfileDefinition>& outDefinitions,
                                                         std::string& outError) {
    outDefinitions.clear();
    if (apiVersion < kExternalModApiVersionV4) {
        outError = "sceneProfileDefinitions requires apiVersion 4";
        return false;
    }

    nlohmann::json json;
    try {
        json = nlohmann::json::parse(content);
    } catch (const std::exception& ex) {
        outError = std::string("scene_profiles.json parse error: ") + ex.what();
        return false;
    }

    if (!json.is_object() || !json.contains("schemaVersion") || !json["schemaVersion"].is_number_integer() ||
        json["schemaVersion"].get<int32_t>() != 1) {
        outError = "scene_profiles.json schemaVersion must be 1";
        return false;
    }
    if (!json.contains("profiles") || !json["profiles"].is_array()) {
        outError = "scene_profiles.json must contain profiles[]";
        return false;
    }

    std::unordered_set<std::string> seenIds;
    for (size_t i = 0; i < json["profiles"].size(); ++i) {
        const auto& profile = json["profiles"][i];
        if (!profile.is_object()) {
            outError = "profiles[" + std::to_string(i) + "] must be object";
            return false;
        }

        ExternalModSceneProfileDefinition definition;
        if (!ValidateRequiredString(profile, "id", definition.id, outError)) {
            outError = "profiles[" + std::to_string(i) + "].id: " + outError;
            return false;
        }
        if (!IsNamespacedCatalogId(definition.id)) {
            outError = "profiles[" + std::to_string(i) + "].id must be namespaced";
            return false;
        }
        if (!seenIds.insert(definition.id).second) {
            outError = "Duplicate scene profile id: " + definition.id;
            return false;
        }
        if (profile.contains("sceneId")) {
            if (!profile["sceneId"].is_number_integer()) {
                outError = "profiles[" + std::to_string(i) + "].sceneId must be integer";
                return false;
            }
            definition.sceneId = static_cast<int16_t>(profile["sceneId"].get<int32_t>());
        }
        if (profile.contains("postFxPresetId")) {
            if (!profile["postFxPresetId"].is_string()) {
                outError = "profiles[" + std::to_string(i) + "].postFxPresetId must be string";
                return false;
            }
            definition.postFxPresetId = profile["postFxPresetId"].get<std::string>();
        }
        if (profile.contains("skylightProfileId")) {
            if (!profile["skylightProfileId"].is_string()) {
                outError = "profiles[" + std::to_string(i) + "].skylightProfileId must be string";
                return false;
            }
            definition.skylightProfileId = profile["skylightProfileId"].get<std::string>();
        }
        if (profile.contains("ambientColor")) {
            if (!profile["ambientColor"].is_array() || profile["ambientColor"].size() != 3) {
                outError = "profiles[" + std::to_string(i) + "].ambientColor must be [r,g,b]";
                return false;
            }
            for (size_t c = 0; c < 3; ++c) {
                if (!profile["ambientColor"][c].is_number()) {
                    outError = "profiles[" + std::to_string(i) + "].ambientColor must be numeric";
                    return false;
                }
                definition.ambientColor[c] = std::clamp(profile["ambientColor"][c].get<float>(), 0.0f, 1.0f);
            }
        }

        outDefinitions.push_back(std::move(definition));
    }

    return true;
}

