void ExternalModManager::OnPlayerUpdate() {
    if (gPlayState != nullptr) {
        auto* player = GET_PLAYER(gPlayState);
        if (player != nullptr) {
            bool forceControlLock = false;
            bool forceFrozenState = false;
            float gravityScale = 1.0f;
            bool hasGravityOverride = false;
            for (const auto& package : mPackages) {
                if (!package.runtime.enabled) {
                    continue;
                }
                const auto lockIt = package.runtime.globalBlackboard.find("__playerControlLocked");
                if (lockIt != package.runtime.globalBlackboard.end() && lockIt->second == "1") {
                    forceControlLock = true;
                }
                const auto frozenIt = package.runtime.globalBlackboard.find("__player_stateflag.frozen");
                if (frozenIt != package.runtime.globalBlackboard.end() && frozenIt->second == "1") {
                    forceFrozenState = true;
                }
                const auto gravityIt = package.runtime.globalBlackboard.find("__playerGravityScale");
                if (gravityIt != package.runtime.globalBlackboard.end()) {
                    float parsed = 1.0f;
                    if (TryParseFloatString(gravityIt->second, parsed)) {
                        gravityScale = std::clamp(parsed, 0.1f, 5.0f);
                        hasGravityOverride = true;
                    }
                }
            }

            if (forceControlLock) {
                auto* input = &gPlayState->state.input[0];
                input->cur.button = 0;
                input->press.button = 0;
                player->actor.speedXZ = 0.0f;
            }

            if (forceFrozenState && !(player->stateFlags2 & PLAYER_STATE2_FROZEN)) {
                func_80837C0C(gPlayState, player, PLAYER_HIT_RESPONSE_ICE_TRAP, 0.0f, 0.0f, player->actor.shape.rot.y, 20);
            } else if (!forceFrozenState && (player->stateFlags2 & PLAYER_STATE2_FROZEN) && player->actor.freezeTimer == 0) {
                player->stateFlags2 &= ~PLAYER_STATE2_FROZEN;
            }

            if (hasGravityOverride) {
                const float baseGravity = player->actor.gravity < -0.05f ? std::abs(player->actor.gravity) : 1.0f;
                player->actor.gravity = -std::clamp(baseGravity * gravityScale, 0.1f, 20.0f);
            }

            ExternalModPackage* selectedSurfPackage = nullptr;
            for (auto& package : mPackages) {
                if (!package.runtime.enabled || !package.runtime.surfState.active) {
                    continue;
                }
                if (selectedSurfPackage == nullptr || package.manifest.loadPriority > selectedSurfPackage->manifest.loadPriority ||
                    (package.manifest.loadPriority == selectedSurfPackage->manifest.loadPriority &&
                     package.manifest.id < selectedSurfPackage->manifest.id)) {
                    selectedSurfPackage = &package;
                }
            }
            if (selectedSurfPackage != nullptr) {
                TickSurfState(*selectedSurfPackage, gPlayState, player);
            }

            if (mPlayerResourcesRuntime) {
                const auto resolver = BuildPlayerResourceSettingsResolver(*this);
                for (auto& package : mPackages) {
                    if (!package.runtime.enabled || package.runtime.playerResourceDefinitions.empty()) {
                        continue;
                    }
                    mPlayerResourcesRuntime->TickPackage(package, gPlayState, player, resolver);
                }
            }
        }
    }

    ExternalModHookEventContext context;
    if (gPlayState != nullptr) {
        context.scene = static_cast<int16_t>(gPlayState->sceneNum);
    }
    DispatchExtendedHook(ExternalModHookType::OnPlayerUpdate, context, "OnPlayerUpdate");
}

void ExternalModManager::OnPlayDrawBegin() {
    if (mWorldGraphicsRuntime) {
        mWorldGraphicsRuntime->OnPlayDrawBegin(*this, mPackages, gPlayState);
    }
}

void ExternalModManager::OnPlayDrawEnd() {
    DrawPrefabVisuals(gPlayState);

    if (mWorldGraphicsRuntime) {
        mWorldGraphicsRuntime->OnPlayDrawEnd(gPlayState);
    }

    static int32_t renderInspectorCooldown = 0;
    if (renderInspectorCooldown > 0) {
        renderInspectorCooldown--;
    }

    if (!mWorldGraphicsRuntime || renderInspectorCooldown > 0 || !IsRenderInspectorDebugGateActive()) {
        return;
    }

    for (const auto& package : mPackages) {
        if (!package.runtime.enabled) {
            continue;
        }
        bool anyVisible = false;
        for (const auto& inspector : package.runtime.renderInspectorDefinitions) {
            bool visible = false;
            if (GetRenderInspectorOverlayVisible(package.manifest.id, inspector.id, visible) && visible) {
                anyVisible = true;
                break;
            }
        }
        if (!anyVisible) {
            continue;
        }
        const auto summary = mWorldGraphicsRuntime->BuildInspectorSummary();
        if (!summary.empty()) {
            Notification::Emit({
                .message = std::string("[RenderInspector] ") + summary,
                .remainingTime = 3.0f,
            });
            renderInspectorCooldown = 120;
        }
        break;
    }
}

void ExternalModManager::OnGameFrameUpdate() {
    if (gPlayState == nullptr) {
        return;
    }

    auto* player = GET_PLAYER(gPlayState);
    if (player == nullptr) {
        return;
    }

    const auto sceneNum = static_cast<int16_t>(gPlayState->sceneNum);
    const auto playerPos = player->actor.world.pos;
    auto* input = &gPlayState->state.input[0];
    const bool interactPressed = MatchPressedButtonMask(input->cur.button, input->prev.button, BTN_A);

    for (auto& package : mPackages) {
        if (!package.runtime.enabled || package.runtime.playerConsumableDefinitions.empty()) {
            continue;
        }
        SyncInventoryBackedConsumablesForPackage(package, gPlayState, player);
    }

    ProcessAssignedActionButtons(gPlayState, player, input);

    bool hasPendingReloadRequest = false;
    std::string pendingReloadTarget = "all";
    int32_t pendingReloadPriority = std::numeric_limits<int32_t>::min();
    std::string pendingReloadModId;

    for (auto& package : mPackages) {
        if (!package.runtime.enabled) {
            continue;
        }

        package.runtime.hookCallsThisFrame = 0;
        package.runtime.behaviorStepsThisFrame = 0;
        package.runtime.wasmCallsThisFrame = 0;
        package.runtime.wasmBudgetDropsThisFrame = 0;
        package.runtime.wasmTargetHandles.clear();
        if (package.runtime.wasmRuntime) {
            package.runtime.wasmRuntime->BeginFrame();
        }
        if (package.runtime.nativeRuntime) {
            std::string nativeError;
            if (!package.runtime.nativeRuntime->BeginFrame(nativeError)) {
                DisableRuntime(package, "Native runtime frame callback failed: " + nativeError);
                continue;
            }
        }
        for (auto& hookSubscription : package.runtime.hookSubscriptions) {
            if (hookSubscription.cooldownRemaining > 0) {
                hookSubscription.cooldownRemaining--;
            }
        }
        if (package.runtime.hotReloadCooldownMs > 0) {
            package.runtime.hotReloadCooldownMs = std::max(0, package.runtime.hotReloadCooldownMs - 16);
        }

        for (auto it = package.runtime.spellCooldownsById.begin(); it != package.runtime.spellCooldownsById.end();) {
            if (it->second > 0) {
                it->second--;
            }
            if (it->second <= 0) {
                it = package.runtime.spellCooldownsById.erase(it);
            } else {
                ++it;
            }
        }

        for (size_t processIndex = 0; processIndex < package.runtime.activeContainerProcesses.size();) {
            auto& process = package.runtime.activeContainerProcesses[processIndex];
            if (process.remainingMs > 0) {
                process.remainingMs = std::max(0, process.remainingMs - 16);
            }

            ExternalModHookEventContext tickContext;
            tickContext.scene = sceneNum;
            tickContext.value = process.containerId;
            DispatchExtendedHook(ExternalModHookType::OnProcessTick, tickContext, "OnProcessTick");

            if (process.remainingMs == 0) {
                ExternalModHookEventContext completeContext;
                completeContext.scene = sceneNum;
                completeContext.value = process.containerId;
                DispatchExtendedHook(ExternalModHookType::OnProcessComplete, completeContext, "OnProcessComplete");
                package.runtime.activeContainerProcesses.erase(
                    package.runtime.activeContainerProcesses.begin() + static_cast<std::ptrdiff_t>(processIndex));
                continue;
            }

            ++processIndex;
        }

        TickRuntimeFxHandles(package.runtime);

        try {
            for (size_t stateIndex = 0; stateIndex < package.runtime.activeStates.size();) {
                auto& state = package.runtime.activeStates[stateIndex];
                Actor* stateActor = FindActorByAddress(gPlayState, state.actorAddress, state.actorId);
                if (stateActor == nullptr || stateActor->update == nullptr) {
                    package.runtime.activeStates.erase(package.runtime.activeStates.begin() +
                                                      static_cast<std::ptrdiff_t>(stateIndex));
                    continue;
                }

                if (state.framesRemaining > 0) {
                    state.framesRemaining--;
                }

                if (state.framesRemaining == 0) {
                    const auto* definition = ResolveStateDefinitionById(package.runtime, state.stateId);
                    if (definition != nullptr && !definition->onRemove.empty()) {
                        ExecuteActions(package, definition->onRemove, "states.onExpire");
                    }
                    ExternalModHookEventContext stateContext;
                    stateContext.scene = static_cast<int16_t>(gPlayState->sceneNum);
                    stateContext.actorId = state.actorId;
                    stateContext.actorCategory = stateActor->category;
                    stateContext.stateId = state.stateId;
                    DispatchExtendedHook(ExternalModHookType::OnStateRemoved, stateContext, "OnStateRemoved");
                    package.runtime.activeStates.erase(package.runtime.activeStates.begin() +
                                                      static_cast<std::ptrdiff_t>(stateIndex));
                    continue;
                }

                ++stateIndex;
            }

            for (auto& trigger : package.runtime.frameTriggers) {
                if (trigger.sceneId != sceneNum) {
                    trigger.wasInside = false;
                    continue;
                }
                if (trigger.cooldownRemaining > 0) {
                    trigger.cooldownRemaining--;
                }

                const bool inside = IsWithinAabb(trigger, playerPos);
                if (inside && !trigger.wasInside && trigger.cooldownRemaining == 0) {
                    ExecuteActions(package, trigger.actions, trigger.id.c_str());
                    trigger.cooldownRemaining = trigger.cooldownFrames;
                }
                trigger.wasInside = inside;
            }

            std::erase_if(package.runtime.inputTriggers, [&](const ExternalModInputActionTrigger& inputTrigger) {
                const auto bindingIt = std::find_if(package.runtime.inputBindings.begin(), package.runtime.inputBindings.end(),
                                                    [&](const ExternalModInputBinding& binding) {
                                                        return binding.id == inputTrigger.bindingId;
                                                    });
                if (bindingIt != package.runtime.inputBindings.end()) {
                    return false;
                }

                AddPackageIssue(package, ExternalModIssueSeverity::Error, "V52_REF_UNKNOWN_INPUT_BINDING",
                                "onInput references unknown binding: " + inputTrigger.bindingId, "scripts/init.json",
                                "core.input.v1", inputTrigger.bindingId,
                                "Add the binding to inputDefinitions or remove the onInput trigger.");
                return true;
            });

            for (auto& inputTrigger : package.runtime.inputTriggers) {
                if (inputTrigger.cooldownRemaining > 0) {
                    inputTrigger.cooldownRemaining--;
                }

                const auto bindingIt = std::find_if(package.runtime.inputBindings.begin(), package.runtime.inputBindings.end(),
                                                    [&inputTrigger](const ExternalModInputBinding& binding) {
                                                        return binding.id == inputTrigger.bindingId;
                                                    });
                if (bindingIt == package.runtime.inputBindings.end()) {
                    continue;
                }

                const auto cvarName = BuildBindingCVarName(package.manifest.id, bindingIt->id);
                int32_t effectiveMask = bindingIt->allowUserRemap ? CVarGetInteger(cvarName.c_str(), bindingIt->defaultMask)
                                                                  : bindingIt->defaultMask;
                if (effectiveMask == 0) {
                    effectiveMask = bindingIt->defaultMask;
                }

                bool active = false;
                switch (inputTrigger.trigger) {
                    case ExternalModInputTriggerType::Pressed:
                        active = MatchPressedButtonMask(input->cur.button, input->prev.button, effectiveMask);
                        break;
                    case ExternalModInputTriggerType::Held:
                        active = MatchButtonMask(input->cur.button, effectiveMask);
                        break;
                    case ExternalModInputTriggerType::Released:
                        active = MatchReleasedButtonMask(input->cur.button, input->prev.button, effectiveMask);
                        break;
                    default:
                        break;
                }

                if (active && inputTrigger.cooldownRemaining == 0) {
                    ExecuteActions(package, inputTrigger.actions, inputTrigger.id.c_str());
                    inputTrigger.cooldownRemaining = inputTrigger.cooldownFrames;
                }
            }

            std::string aoeTickError;
            if (!TickActiveAoEs(package, gPlayState, player, aoeTickError)) {
                DisableRuntime(package, aoeTickError);
                break;
            }
            if (!package.runtime.enabled) {
                break;
            }

            std::vector<DeferredStatusCallback> deferredStatusCallbacks;
            TickStatusEffects(package, gPlayState, deferredStatusCallbacks);
            for (const auto& callback : deferredStatusCallbacks) {
                if (!package.runtime.enabled) {
                    break;
                }
                if (!callback.actions.empty()) {
                    const auto addrIt = package.runtime.globalBlackboard.find("__fxTargetActorAddress");
                    const bool hadOldAddress = addrIt != package.runtime.globalBlackboard.end();
                    const std::string oldAddress = hadOldAddress ? addrIt->second : "";
                    const auto idIt = package.runtime.globalBlackboard.find("__fxTargetActorId");
                    const bool hadOldId = idIt != package.runtime.globalBlackboard.end();
                    const std::string oldId = hadOldId ? idIt->second : "";

                    if (callback.actorAddress != 0) {
                        package.runtime.globalBlackboard["__fxTargetActorAddress"] =
                            std::to_string(static_cast<uint64_t>(callback.actorAddress));
                        package.runtime.globalBlackboard["__fxTargetActorId"] =
                            std::to_string(static_cast<int32_t>(callback.actorId));
                    }
                    ExecuteActions(package, callback.actions, callback.triggerName.c_str());

                    if (callback.actorAddress != 0) {
                        if (hadOldAddress) {
                            package.runtime.globalBlackboard["__fxTargetActorAddress"] = oldAddress;
                        } else {
                            package.runtime.globalBlackboard.erase("__fxTargetActorAddress");
                        }
                        if (hadOldId) {
                            package.runtime.globalBlackboard["__fxTargetActorId"] = oldId;
                        } else {
                            package.runtime.globalBlackboard.erase("__fxTargetActorId");
                        }
                    }
                }
            }
            if (!package.runtime.enabled) {
                break;
            }

            for (auto& item : package.runtime.itemDefinitions) {
                if (!item.granted) {
                    continue;
                }

                if (GetParamOrDefault(item.params, "infiniteAmmo", 0.0f) > 0.0f) {
                    int32_t ammoItemId = ResolveGrantedAmmoItemId(item);
                    if (ammoItemId == ITEM_NONE && item.hasGrantItemId) {
                        ammoItemId = item.grantItemId;
                    }
                    if (ammoItemId != ITEM_NONE) {
                        const int32_t refillTarget = std::max(item.hasGrantAmmo ? item.grantAmmo : 0, 30);
                        AMMO(ammoItemId) = static_cast<int8_t>(std::clamp(refillTarget, 0, 99));
                    }
                }

                const bool cooldownWasActive = item.cooldownRemaining > 0;
                if (item.cooldownRemaining > 0) {
                    item.cooldownRemaining--;
                }

                if (cooldownWasActive && item.cooldownRemaining == 0) {
                    std::unordered_set<std::string> behaviorIds;
                    if (!item.onUseBehavior.empty()) {
                        behaviorIds.insert(item.onUseBehavior);
                    }
                    if (!item.onEquipBehavior.empty()) {
                        behaviorIds.insert(item.onEquipBehavior);
                    }

                    for (const auto& behaviorId : behaviorIds) {
                        int32_t stepCount = package.runtime.behaviorStepsThisFrame;
                        std::vector<ExternalModAction> cooldownActions;
                        std::string behaviorError;
                        if (!CollectBehaviorEventActions(package, behaviorId, "oncooldownready", nullptr,
                                                         package.runtime.behaviorMaxStepsPerModPerFrame, stepCount,
                                                         cooldownActions, behaviorError)) {
                            DisableRuntime(package, "onCooldownReady behavior failed for item '" + item.id +
                                                        "': " + behaviorError);
                            break;
                        }
                        package.runtime.behaviorStepsThisFrame = stepCount;
                        if (!cooldownActions.empty()) {
                            ExecuteActions(package, cooldownActions, "itemOnCooldownReady");
                        }
                    }
                    if (!package.runtime.enabled) {
                        break;
                    }
                }

                if (!item.granted || item.onUpdateExport.empty()) {
                    continue;
                }
                if (!package.runtime.wasmRuntime) {
                    continue;
                }

                std::string wasmError;
                if (!package.runtime.wasmRuntime->InvokeExport(item.onUpdateExport, wasmError)) {
                    DisableRuntime(package, "WASM onUpdate failed for item '" + item.id + "': " + wasmError);
                    break;
                }
            }

            if (!package.runtime.enabled) {
                continue;
            }

            for (size_t lightIndex = 0; lightIndex < package.runtime.activeDynamicLights.size();) {
                auto& light = package.runtime.activeDynamicLights[lightIndex];
                if (light.remainingMs > 0) {
                    light.remainingMs = std::max(0, light.remainingMs - 16);
                }
                if (light.remainingMs == 0) {
                    ExternalModHookEventContext lightExpiredContext;
                    lightExpiredContext.scene = gPlayState != nullptr ? gPlayState->sceneNum : -1;
                    lightExpiredContext.actorHandle = light.handle;
                    lightExpiredContext.value = light.profileId;
                    DispatchExtendedHook(ExternalModHookType::OnRenderLightExpired, lightExpiredContext,
                                         "OnRenderLightExpired");
                    package.runtime.activeDynamicLights.erase(
                        package.runtime.activeDynamicLights.begin() + static_cast<std::ptrdiff_t>(lightIndex));
                    continue;
                }
                ++lightIndex;
            }
            for (size_t overrideIndex = 0; overrideIndex < package.runtime.materialOverrides.size();) {
                auto& overrideState = package.runtime.materialOverrides[overrideIndex];
                if (overrideState.framesRemaining > 0) {
                    overrideState.framesRemaining--;
                }
                if (overrideState.framesRemaining == 0) {
                    package.runtime.materialOverrides.erase(
                        package.runtime.materialOverrides.begin() + static_cast<std::ptrdiff_t>(overrideIndex));
                    continue;
                }
                ++overrideIndex;
            }
            if (package.runtime.activePostFxRemainingMs > 0) {
                package.runtime.activePostFxRemainingMs = std::max(0, package.runtime.activePostFxRemainingMs - 16);
                if (package.runtime.activePostFxRemainingMs == 0 && package.runtime.activePostFxDurationMs > 0) {
                    package.runtime.activePostFxPresetId.clear();
                    package.runtime.activePostFxOwnerModId.clear();
                    package.runtime.activePostFxDurationMs = 0;
                    package.runtime.activePostFxBlend = 1.0f;
                    package.runtime.globalBlackboard.erase("__render_postfx_preset");
                    package.runtime.globalBlackboard.erase("__render_postfx_blend");
                    package.runtime.globalBlackboard.erase("__render_postfx_duration_ms");
                }
            }

            const int16_t currentRoomNum = static_cast<int16_t>(gPlayState->roomCtx.curRoom.num);
            const bool roomChanged = package.runtime.lastSceneSeen != sceneNum || package.runtime.lastRoomSeen != currentRoomNum;
            const int16_t previousRoomNum = package.runtime.lastRoomSeen;

            if (roomChanged && RuntimeHasPersistentState(package.runtime)) {
                bool autoSaveOnRoomExit = package.runtime.worldPersistenceDefinitions.empty();
                bool autoLoadOnRoomEnter = package.runtime.worldPersistenceDefinitions.empty();
                for (const auto& persistenceDefinition : package.runtime.worldPersistenceDefinitions) {
                    autoSaveOnRoomExit = autoSaveOnRoomExit || persistenceDefinition.autoSaveOnRoomExit;
                    autoLoadOnRoomEnter = autoLoadOnRoomEnter || persistenceDefinition.autoLoadOnRoomEnter;
                }

                if (autoSaveOnRoomExit && package.runtime.persistentStateDirty) {
                    PersistRuntimeStateForPackage(package);
                    package.runtime.persistentStateDirty = false;
                }
                if (autoLoadOnRoomEnter) {
                    LoadRuntimeStateForPackage(package);
                }
            }

            package.runtime.lastSceneSeen = sceneNum;
            package.runtime.lastRoomSeen = currentRoomNum;

            const bool isNight = gSaveContext.dayTime >= 0xC000 || gSaveContext.dayTime < 0x4555;
            bool timeOfDayChanged = false;
            if (!package.runtime.hasLastDayNight) {
                package.runtime.lastIsNight = isNight;
                package.runtime.hasLastDayNight = true;
            } else if (package.runtime.lastIsNight != isNight) {
                package.runtime.lastIsNight = isNight;
                timeOfDayChanged = true;
            }

            int16_t skyboxId = -1;
            if (gPlayState->skyboxId >= std::numeric_limits<int16_t>::min() &&
                gPlayState->skyboxId <= std::numeric_limits<int16_t>::max()) {
                skyboxId = static_cast<int16_t>(gPlayState->skyboxId);
            }
            const bool skyboxChanged =
                package.runtime.lastSkyboxSeen == -1 ? false : (package.runtime.lastSkyboxSeen != skyboxId);
            package.runtime.lastSkyboxSeen = skyboxId;

            const std::string currentTimeSegment = package.runtime.worldTimeSegment.empty()
                                                       ? std::string("day")
                                                       : ToLower(package.runtime.worldTimeSegment);
            const std::string currentWeatherState = package.runtime.worldWeatherState.empty()
                                                        ? std::string("clear")
                                                        : ToLower(package.runtime.worldWeatherState);
            const std::string previousTimeSegment =
                package.runtime.globalBlackboard.contains("__world_time_segment_last")
                    ? package.runtime.globalBlackboard["__world_time_segment_last"]
                    : "";
            const std::string previousWeatherState =
                package.runtime.globalBlackboard.contains("__world_weather_state_last")
                    ? package.runtime.globalBlackboard["__world_weather_state_last"]
                    : "";
            const bool worldTimeSegmentChanged = !previousTimeSegment.empty() && previousTimeSegment != currentTimeSegment;
            const bool worldWeatherChanged = !previousWeatherState.empty() && previousWeatherState != currentWeatherState;
            package.runtime.globalBlackboard["__world_time_segment_last"] = currentTimeSegment;
            package.runtime.globalBlackboard["__world_weather_state_last"] = currentWeatherState;
            package.runtime.globalBlackboard["__world_time_segment"] = currentTimeSegment;
            package.runtime.globalBlackboard["__world_weather_state"] = currentWeatherState;

            ExternalModHookEventContext overworldTickContext;
            overworldTickContext.scene = sceneNum;
            overworldTickContext.value = isNight ? "night" : "day";
            DispatchExtendedHook(ExternalModHookType::OnWorldOverworldTick, overworldTickContext, "OnWorldOverworldTick");
            if (roomChanged) {
                if (previousRoomNum >= 0) {
                    ExternalModHookEventContext roomExitContext;
                    roomExitContext.scene = sceneNum;
                    roomExitContext.value = std::to_string(previousRoomNum);
                    DispatchExtendedHook(ExternalModHookType::OnWorldRoomExited, roomExitContext, "OnWorldRoomExited");
                }
                ExternalModHookEventContext roomEnterContext;
                roomEnterContext.scene = sceneNum;
                roomEnterContext.value = std::to_string(currentRoomNum);
                DispatchExtendedHook(ExternalModHookType::OnWorldRoomEntered, roomEnterContext, "OnWorldRoomEntered");
            }
            if (timeOfDayChanged) {
                ExternalModHookEventContext todContext;
                todContext.scene = sceneNum;
                todContext.value = isNight ? "night" : "day";
                DispatchExtendedHook(ExternalModHookType::OnWorldTimeOfDayChanged, todContext,
                                     "OnWorldTimeOfDayChanged");
            }
            if (skyboxChanged) {
                ExternalModHookEventContext skyboxContext;
                skyboxContext.scene = sceneNum;
                skyboxContext.value = std::to_string(skyboxId);
                DispatchExtendedHook(ExternalModHookType::OnWorldSkyboxChanged, skyboxContext, "OnWorldSkyboxChanged");
            }
            if (worldTimeSegmentChanged) {
                ExternalModHookEventContext timeSegmentContext;
                timeSegmentContext.scene = sceneNum;
                timeSegmentContext.value = currentTimeSegment;
                DispatchExtendedHook(ExternalModHookType::OnWorldTimeSegmentChanged, timeSegmentContext,
                                     "world.time.segmentChanged");
            }
            if (worldWeatherChanged) {
                ExternalModHookEventContext weatherContext;
                weatherContext.scene = sceneNum;
                weatherContext.value = currentWeatherState;
                DispatchExtendedHook(ExternalModHookType::OnWorldWeatherChanged, weatherContext, "world.weather.changed");
            }

            bool switchFlagChanged = false;
            int32_t changedSwitchFlag = -1;
            bool changedSwitchValue = false;
            if (!package.runtime.switchSnapshotInitialized) {
                for (size_t flag = 0; flag < package.runtime.switchSnapshot.size(); ++flag) {
                    package.runtime.switchSnapshot[flag] = Flags_GetSwitch(gPlayState, static_cast<int32_t>(flag)) ? 1 : 0;
                }
                package.runtime.switchSnapshotInitialized = true;
            } else {
                for (size_t flag = 0; flag < package.runtime.switchSnapshot.size(); ++flag) {
                    const uint8_t current = Flags_GetSwitch(gPlayState, static_cast<int32_t>(flag)) ? 1 : 0;
                    if (current != package.runtime.switchSnapshot[flag]) {
                        switchFlagChanged = true;
                        changedSwitchFlag = static_cast<int32_t>(flag);
                        changedSwitchValue = current != 0;
                    }
                    package.runtime.switchSnapshot[flag] = current;
                }
            }
            if (switchFlagChanged && changedSwitchFlag >= 0) {
                package.runtime.globalBlackboard["__switchFlag"] = std::to_string(changedSwitchFlag);
                package.runtime.globalBlackboard["__switchValue"] = changedSwitchValue ? "1" : "0";
            }

            for (auto timelineIt = package.runtime.activeTimelines.begin();
                 timelineIt != package.runtime.activeTimelines.end();) {
                auto& timelineState = timelineIt->second;
                const auto timelineDefinitionIt =
                    std::find_if(package.runtime.narrativeTimelineDefinitions.begin(),
                                 package.runtime.narrativeTimelineDefinitions.end(),
                                 [&](const ExternalModNarrativeTimelineDefinition& definition) {
                                     return definition.id == timelineState.timelineId;
                                 });
                if (timelineDefinitionIt == package.runtime.narrativeTimelineDefinitions.end()) {
                    timelineIt = package.runtime.activeTimelines.erase(timelineIt);
                    continue;
                }

                const int32_t previousFrame = timelineState.frame;
                timelineState.frame = std::max(0, timelineState.frame + 1);
                for (const auto& track : timelineDefinitionIt->tracks) {
                    if (track.atFrame > previousFrame && track.atFrame <= timelineState.frame && !track.actions.empty()) {
                        ExecuteActions(package, track.actions, "narrative.timeline.track");
                        if (!package.runtime.enabled) {
                            break;
                        }
                    }
                }
                if (!package.runtime.enabled) {
                    break;
                }

                bool hasFutureTrack = false;
                for (const auto& track : timelineDefinitionIt->tracks) {
                    if (track.atFrame > timelineState.frame) {
                        hasFutureTrack = true;
                        break;
                    }
                }
                const bool timelineCompleted =
                    timelineState.durationFrames > 0 ? (timelineState.frame >= timelineState.durationFrames) : !hasFutureTrack;
                if (timelineCompleted) {
                    if (!timelineDefinitionIt->onCompleted.empty()) {
                        ExecuteActions(package, timelineDefinitionIt->onCompleted, "narrative.timeline.completed");
                        if (!package.runtime.enabled) {
                            break;
                        }
                    }
                    ExternalModHookEventContext context;
                    context.scene = sceneNum;
                    context.value = timelineState.timelineId;
                    DispatchExtendedHook(ExternalModHookType::OnTimelineCompleted, context, "OnTimelineCompleted");
                    timelineIt = package.runtime.activeTimelines.erase(timelineIt);
                    continue;
                }

                ++timelineIt;
            }
            if (!package.runtime.enabled) {
                continue;
            }

            for (const auto& spawnProfile : package.runtime.worldSpawnProfiles) {
                const std::string resolvedArchetypeId =
                    ResolveProfileIdForMod(package.manifest.id, spawnProfile.actorArchetypeId);
                if (resolvedArchetypeId.empty()) {
                    continue;
                }

                int32_t activeCount = 0;
                for (const auto& instance : package.runtime.actorInstances) {
                    if (!instance.active || instance.sceneId != sceneNum || instance.definitionId != resolvedArchetypeId) {
                        continue;
                    }
                    activeCount++;
                }
                if (activeCount >= std::max(0, spawnProfile.maxActive)) {
                    continue;
                }

                const std::string cooldownKey = "__world_spawn_cooldown." + spawnProfile.id;
                int32_t cooldownRemaining = 0;
                if (const auto cooldownIt = package.runtime.globalBlackboard.find(cooldownKey);
                    cooldownIt != package.runtime.globalBlackboard.end()) {
                    try {
                        cooldownRemaining = std::max(0, std::stoi(cooldownIt->second));
                    } catch (...) {
                        cooldownRemaining = 0;
                    }
                }
                if (cooldownRemaining > 0) {
                    package.runtime.globalBlackboard[cooldownKey] = std::to_string(std::max(0, cooldownRemaining - 1));
                    continue;
                }

                ExternalModAction spawnAction;
                spawnAction.type = ExternalModActionType::ActorsSpawnArchetype;
                spawnAction.archetypeId = resolvedArchetypeId;
                spawnAction.spawnOrigin = "player_forward";
                spawnAction.forwardDistance =
                    std::clamp(spawnProfile.minDistanceFromPlayer, 40.0f, std::max(spawnProfile.maxDistanceFromPlayer, 40.0f));
                ExecuteActions(package, { spawnAction }, "world.spawnProfile.auto");
                if (!package.runtime.enabled) {
                    break;
                }
                package.runtime.globalBlackboard[cooldownKey] = std::to_string(std::max(1, spawnProfile.cooldownFrames));

                ExternalModHookEventContext context;
                context.scene = sceneNum;
                context.value = spawnProfile.id;
                DispatchExtendedHook(ExternalModHookType::OnWorldSpawnProfileTick, context, "OnWorldSpawnProfileTick");
            }
            if (!package.runtime.enabled) {
                continue;
            }

            for (auto& instance : package.runtime.actorInstances) {
                if (!instance.active || instance.sceneId != sceneNum) {
                    continue;
                }

                const auto* definition = FindActorDefinition(package.runtime, instance.definitionId);
                if (definition == nullptr) {
                    DisableRuntime(package, "Actor instance references missing definition: " + instance.definitionId);
                    break;
                }

                instance.tickCounter++;
                if (instance.tickCounter < std::max(1, definition->tickRate)) {
                    continue;
                }
                instance.tickCounter = 0;

                if (!definition->exportOnUpdate.empty()) {
                    if (!package.runtime.wasmRuntime) {
                        DisableRuntime(package, "Actor exportOnUpdate requires wasm runtime");
                        break;
                    }
                    std::string wasmError;
                    const std::vector<int32_t> args = { static_cast<int32_t>(instance.handle), instance.sceneId };
                    if (!package.runtime.wasmRuntime->InvokeExport(definition->exportOnUpdate, args, wasmError)) {
                        DisableRuntime(package,
                                       "Actor exportOnUpdate failed for '" + definition->id + "': " + wasmError);
                        break;
                    }
                }

                const float dx = playerPos.x - instance.posX;
                const float dy = playerPos.y - instance.posY;
                const float dz = playerPos.z - instance.posZ;
                const float distanceToPlayer = std::sqrt(dx * dx + dy * dy + dz * dz);
                const bool nearPlayer = distanceToPlayer <= definition->interactDistance;

                int32_t actorBehaviorSteps = 0;
                auto runBehaviorEvent = [&](const std::string& eventName, const char* source) -> bool {
                    if (definition->behaviorId.empty()) {
                        return true;
                    }
                    int32_t stepCount = package.runtime.behaviorStepsThisFrame;
                    std::vector<ExternalModAction> behaviorActions;
                    std::string behaviorError;
                    if (!CollectBehaviorEventActions(package, definition->behaviorId, eventName, &instance,
                                                     package.runtime.behaviorMaxStepsPerModPerFrame, stepCount,
                                                     behaviorActions, behaviorError)) {
                        DisableRuntime(package, std::string(source) + " behavior failed for actor '" + definition->id +
                                                "': " + behaviorError);
                        return false;
                    }

                    const int32_t stepDelta = stepCount - package.runtime.behaviorStepsThisFrame;
                    actorBehaviorSteps += std::max(stepDelta, 0);
                    package.runtime.behaviorStepsThisFrame = stepCount;
                    if (actorBehaviorSteps > package.runtime.behaviorMaxStepsPerActorPerFrame) {
                        DisableRuntime(package, "behavior step budget exceeded for actor '" + definition->id + "'");
                        return false;
                    }
                    if (!behaviorActions.empty()) {
                        ExecuteActions(package, behaviorActions, source);
                    }
                    return package.runtime.enabled;
                };

                if (!runBehaviorEvent("onupdate", "actorOnUpdate")) {
                    break;
                }
                if (!runBehaviorEvent("onrandomtick", "actorOnRandomTick")) {
                    break;
                }
                if (roomChanged && !runBehaviorEvent("onroomenter", "actorOnRoomEnter")) {
                    break;
                }
                if (timeOfDayChanged && !runBehaviorEvent("ontimeofdaychanged", "actorOnTimeOfDayChanged")) {
                    break;
                }
                if (switchFlagChanged && !runBehaviorEvent("onswitchflagchanged", "actorOnSwitchFlagChanged")) {
                    break;
                }

                if (nearPlayer && !instance.wasNearPlayer) {
                    if (!runBehaviorEvent("onplayernear", "actorOnPlayerNear")) {
                        break;
                    }
                } else if (!nearPlayer && instance.wasNearPlayer) {
                    if (!runBehaviorEvent("onplayerfar", "actorOnPlayerFar")) {
                        break;
                    }
                }
                instance.wasNearPlayer = nearPlayer;

                if (instance.timerFrames > 0) {
                    instance.timerFrames--;
                    if (instance.timerFrames == 0) {
                        if (!runBehaviorEvent("ontimer", "actorOnTimer")) {
                            break;
                        }
                    }
                }

                if (interactPressed && definition->interactable && nearPlayer) {
                    if (package.runtime.wasmRuntime && !definition->exportOnInteract.empty()) {
                        std::string wasmError;
                        const std::vector<int32_t> args = { static_cast<int32_t>(instance.handle), instance.sceneId };
                        if (!package.runtime.wasmRuntime->InvokeExport(definition->exportOnInteract, args, wasmError)) {
                            DisableRuntime(package,
                                           "Actor exportOnInteract failed for '" + definition->id + "': " + wasmError);
                            break;
                        }
                    }
                    if (!runBehaviorEvent("oninteract", "actorOnInteract")) {
                        break;
                    }
                }
            }

            if (!package.runtime.enabled) {
                continue;
            }

            if (!package.runtime.pendingSignals.empty()) {
                const auto pendingSignals = package.runtime.pendingSignals;
                package.runtime.pendingSignals.clear();
                for (const auto& signal : pendingSignals) {
                    package.runtime.globalBlackboard["__lastSignal"] = signal.second;
                    for (auto& instance : package.runtime.actorInstances) {
                        if (!instance.active || instance.sceneId != sceneNum) {
                            continue;
                        }
                        if (signal.first != 0 && signal.first != instance.handle) {
                            continue;
                        }
                        const auto* definition = FindActorDefinition(package.runtime, instance.definitionId);
                        if (definition == nullptr || definition->behaviorId.empty()) {
                            continue;
                        }

                        int32_t stepCount = package.runtime.behaviorStepsThisFrame;
                        std::vector<ExternalModAction> signalActions;
                        std::string behaviorError;
                        if (!CollectBehaviorEventActions(package, definition->behaviorId, "onsignal", &instance,
                                                         package.runtime.behaviorMaxStepsPerModPerFrame, stepCount,
                                                         signalActions, behaviorError)) {
                            DisableRuntime(package, "onSignal behavior failed for actor '" + definition->id +
                                                        "': " + behaviorError);
                            break;
                        }
                        package.runtime.behaviorStepsThisFrame = stepCount;
                        if (package.runtime.behaviorStepsThisFrame > package.runtime.behaviorMaxStepsPerModPerFrame) {
                            DisableRuntime(package, "behavior mod budget exceeded while dispatching signals");
                            break;
                        }
                        if (!signalActions.empty()) {
                            ExecuteActions(package, signalActions, "onSignal");
                        }
                    }
                    if (!package.runtime.enabled) {
                        break;
                    }
                }
            }

            if (package.runtime.wasmRuntime) {
                package.runtime.wasmCallsThisFrame = package.runtime.wasmRuntime->GetCallsThisFrame();
                package.runtime.wasmBudgetDropsThisFrame = package.runtime.wasmRuntime->GetBudgetDropsThisFrame();
            }
            if (package.runtime.wasmBudgetDropsThisFrame > 0) {
                ExternalModHookEventContext context;
                context.scene = sceneNum;
                context.value = std::to_string(package.runtime.wasmBudgetDropsThisFrame);
                DispatchExtendedHook(ExternalModHookType::OnSandboxBudgetExceeded, context, "OnSandboxBudgetExceeded");
            }
            if (const auto permissionDeniedIt = package.runtime.globalBlackboard.find("__sandbox_permission_denied");
                permissionDeniedIt != package.runtime.globalBlackboard.end() && !permissionDeniedIt->second.empty()) {
                ExternalModHookEventContext context;
                context.scene = sceneNum;
                context.value = permissionDeniedIt->second;
                DispatchExtendedHook(ExternalModHookType::OnSandboxPermissionDenied, context, "OnSandboxPermissionDenied");
                package.runtime.globalBlackboard.erase(permissionDeniedIt);
            }

            if (package.runtime.hotReloadEnabled && package.runtime.hotReloadCooldownMs <= 0) {
                const auto reloadRequestIt = package.runtime.globalBlackboard.find("__dev_reload_requested");
                if (reloadRequestIt != package.runtime.globalBlackboard.end()) {
                    const std::string target = reloadRequestIt->second.empty() ? "all" : ToLower(reloadRequestIt->second);
                    const bool shouldReplaceRequest = !hasPendingReloadRequest ||
                                                      package.manifest.loadPriority > pendingReloadPriority ||
                                                      (package.manifest.loadPriority == pendingReloadPriority &&
                                                       package.manifest.id < pendingReloadModId);
                    if (shouldReplaceRequest) {
                        hasPendingReloadRequest = true;
                        pendingReloadTarget = target;
                        pendingReloadPriority = package.manifest.loadPriority;
                        pendingReloadModId = package.manifest.id;
                    }
                    package.runtime.hotReloadCooldownMs = std::max(50, package.runtime.hotReloadDebounceMs);
                    package.runtime.globalBlackboard.erase(reloadRequestIt);
                }
            }
        } catch (const std::exception& ex) {
            DisableRuntime(package, std::string("Unhandled exception on onFrame: ") + ex.what());
        } catch (...) {
            DisableRuntime(package, "Unhandled exception on onFrame");
        }
    }

    if (hasPendingReloadRequest) {
        std::string reloadError;
        const bool reloadOk = ReloadPackages(reloadError);
        ExternalModHookEventContext reloadContext;
        reloadContext.scene = sceneNum;
        reloadContext.value = pendingReloadTarget;
        if (reloadOk && reloadError.empty()) {
            DispatchExtendedHook(ExternalModHookType::OnHotReloadApplied, reloadContext, "OnHotReloadApplied");
        } else {
            if (!reloadError.empty()) {
                reloadContext.value += ":" + reloadError;
            }
            DispatchExtendedHook(ExternalModHookType::OnHotReloadFailed, reloadContext, "OnHotReloadFailed");
        }
    }

    ExternalModHookEventContext context;
    context.scene = sceneNum;
    DispatchExtendedHook(ExternalModHookType::OnGameFrameUpdate, context, "OnGameFrameUpdate");

    ApplyGlobalPlayerStatusModifiers(mPackages, gPlayState);

    SyncExtraInventoryGrid();
    ApplyModItemAgeRequirementOverrides(mPackages);
    ApplyModItemIconOverrides(mPackages);
    ApplyModHookshotTextureOverrides(mPackages);
}

bool ExternalModManager::OnHammerGroundImpact(PlayState* play, Player* player, float impactX, float impactY, float impactZ) {
    if (play == nullptr || player == nullptr) {
        return false;
    }

    ExternalModPackage* selectedPackage = nullptr;
    ExternalModItemDefinition* selectedItem = nullptr;
    int32_t selectedPriority = std::numeric_limits<int32_t>::min();
    std::string selectedModId;
    const int32_t heldItemId = player->heldItemId;

    for (auto& package : mPackages) {
        if (!package.runtime.enabled) {
            continue;
        }

        for (auto& item : package.runtime.itemDefinitions) {
            if (!item.granted || item.useTrigger != ExternalModItemUseTrigger::HammerGroundImpact || !item.hasSlot ||
                item.slot != ExternalModItemSlot::Hammer || item.useProfile.empty() || item.cooldownRemaining > 0 ||
                !ItemDefinitionMatchesUseItem(item, heldItemId)) {
                continue;
            }

            const bool shouldReplace = selectedPackage == nullptr || package.manifest.loadPriority > selectedPriority ||
                                       (package.manifest.loadPriority == selectedPriority &&
                                        package.manifest.id < selectedModId);
            if (shouldReplace) {
                selectedPackage = &package;
                selectedItem = &item;
                selectedPriority = package.manifest.loadPriority;
                selectedModId = package.manifest.id;
            }
        }
    }

    if (selectedPackage == nullptr || selectedItem == nullptr) {
        return false;
    }

    auto& runtime = selectedPackage->runtime;
    runtime.hasEffectImpactPosition = true;
    runtime.effectImpactPosX = impactX;
    runtime.effectImpactPosY = impactY;
    runtime.effectImpactPosZ = impactZ;
    runtime.useProfileSpawnedShockwave = false;

    const auto clearImpactContext = [&runtime]() {
        runtime.hasEffectImpactPosition = false;
        runtime.effectImpactPosX = 0.0f;
        runtime.effectImpactPosY = 0.0f;
        runtime.effectImpactPosZ = 0.0f;
        runtime.useProfileSpawnedShockwave = false;
    };

    std::string useProfileError;
    if (!ExecuteUseProfileById(*selectedPackage, selectedItem->useProfile, play, player, selectedItem, useProfileError)) {
        clearImpactContext();
        DisableRuntime(*selectedPackage, "hammerGroundImpact useProfile failed for '" + selectedItem->id +
                                            "': " + useProfileError);
        return false;
    }

    int32_t defaultCooldown = selectedItem->cooldownFrames;
    if (const auto* useProfile =
            ExternalModContentRegistry::FindItemUseProfileById(selectedPackage->runtime, selectedItem->useProfile);
        useProfile != nullptr) {
        defaultCooldown = useProfile->cooldownFrames;
    }
    const auto cooldown = static_cast<int32_t>(
        std::max(0.0f, GetParamOrDefault(selectedItem->params, "cooldown", static_cast<float>(defaultCooldown))));
    selectedItem->cooldownFrames = cooldown;
    selectedItem->cooldownRemaining = cooldown;

    const bool handledShockwave = runtime.useProfileSpawnedShockwave;
    clearImpactContext();
    return handledShockwave;
}

void ExternalModManager::OnPlayerUseItem(void* player, int32_t itemId, bool* allowVanilla) {
    ExternalModHookEventContext hookContext;
    if (gPlayState != nullptr) {
        hookContext.scene = static_cast<int16_t>(gPlayState->sceneNum);
    }
    hookContext.itemId = static_cast<int16_t>(itemId);
    DispatchExtendedHook(ExternalModHookType::OnPlayerUseItem, hookContext, "OnPlayerUseItem");

    if (allowVanilla == nullptr || !*allowVanilla) {
        return;
    }

    for (auto& package : mPackages) {
        if (!package.runtime.enabled) {
            continue;
        }

        for (auto& item : package.runtime.itemDefinitions) {
            if (!item.granted || !ItemDefinitionMatchesUseItem(item, itemId)) {
                continue;
            }

            if (item.useTrigger == ExternalModItemUseTrigger::HammerGroundImpact) {
                continue;
            }

            if (item.cooldownRemaining > 0) {
                if (item.useMode == ExternalModItemUseMode::Override) {
                    *allowVanilla = false;
                    return;
                }
                continue;
            }

            if ((item.useMode == ExternalModItemUseMode::Override || item.useMode == ExternalModItemUseMode::Augment) &&
                package.runtime.wasmRuntime && !item.onUseExport.empty()) {
                std::vector<int32_t> args = { itemId };
                std::string wasmError;
                if (!package.runtime.wasmRuntime->InvokeExport(item.onUseExport, args, wasmError)) {
                    DisableRuntime(package, "WASM onUse failed for item '" + item.id + "': " + wasmError);
                    *allowVanilla = true;
                    return;
                }
            }

            if (!item.onUseBehavior.empty()) {
                int32_t stepCount = package.runtime.behaviorStepsThisFrame;
                std::vector<ExternalModAction> behaviorActions;
                std::string behaviorError;
                if (!CollectBehaviorEventActions(package, item.onUseBehavior, "onitemused", nullptr,
                                                 package.runtime.behaviorMaxStepsPerModPerFrame, stepCount,
                                                 behaviorActions, behaviorError)) {
                    DisableRuntime(package, "onUseBehavior failed for item '" + item.id + "': " + behaviorError);
                    *allowVanilla = true;
                    return;
                }
                package.runtime.behaviorStepsThisFrame = stepCount;
                if (!behaviorActions.empty()) {
                    ExecuteActions(package, behaviorActions, "itemOnUseBehavior");
                    if (!package.runtime.enabled) {
                        *allowVanilla = true;
                        return;
                    }
                }
            }

            if (!item.useProfile.empty() && gPlayState != nullptr) {
                auto* actionPlayer = static_cast<Player*>(player);
                std::string useProfileError;
                if (!ExecuteUseProfileById(package, item.useProfile, gPlayState, actionPlayer, &item, useProfileError)) {
                    DisableRuntime(package, "item useProfile failed for '" + item.id + "': " + useProfileError);
                    *allowVanilla = true;
                    return;
                }
            }

            if (item.slot == ExternalModItemSlot::Hookshot && item.useMode != ExternalModItemUseMode::Vanilla) {
                const float pullForce = GetParamOrDefault(item.params, "pullForce", 8.0f);
                const float speed = GetParamOrDefault(item.params, "speed", 12.0f);
                ExternalModItemRuntime::ApplySkyhookImpulse(player, pullForce, speed);
            }

            int32_t defaultCooldown = item.cooldownFrames;
            if (!item.useProfile.empty()) {
                const auto* useProfile = ExternalModContentRegistry::FindItemUseProfileById(package.runtime, item.useProfile);
                if (useProfile != nullptr) {
                    defaultCooldown = useProfile->cooldownFrames;
                }
            }
            const auto cooldown = static_cast<int32_t>(
                std::max(0.0f, GetParamOrDefault(item.params, "cooldown", static_cast<float>(defaultCooldown))));
            item.cooldownFrames = cooldown;
            item.cooldownRemaining = cooldown;

            if (item.useMode == ExternalModItemUseMode::Override) {
                *allowVanilla = false;
                return;
            }
        }
    }
}

void ExternalModManager::OnPlayerHealthChange(int16_t amount) {
    ExternalModHookEventContext context;
    if (gPlayState != nullptr) {
        context.scene = static_cast<int16_t>(gPlayState->sceneNum);
    }
    context.healthDelta = amount;
    DispatchExtendedHook(ExternalModHookType::OnPlayerHealthChange, context, "OnPlayerHealthChange");
}

void ExternalModManager::OnItemReceive(int16_t itemId) {
    ExternalModHookEventContext context;
    if (gPlayState != nullptr) {
        context.scene = static_cast<int16_t>(gPlayState->sceneNum);
    }
    context.itemId = itemId;
    DispatchExtendedHook(ExternalModHookType::OnItemReceive, context, "OnItemReceive");
}

void ExternalModManager::OnActorHook(ExternalModHookType hookType, void* actor, const char* hookName) {
    ExternalModHookEventContext context;
    if (gPlayState != nullptr) {
        context.scene = static_cast<int16_t>(gPlayState->sceneNum);
    }

    if (actor != nullptr) {
        auto* actorPtr = static_cast<Actor*>(actor);
        context.actorId = static_cast<int16_t>(actorPtr->id);
        context.actorCategory = static_cast<int16_t>(actorPtr->category);
    }

    DispatchExtendedHook(hookType, context, hookName);
}

void ExternalModManager::OnPlayDestroy() {
    ExternalModHookEventContext context;
    if (gPlayState != nullptr) {
        context.scene = static_cast<int16_t>(gPlayState->sceneNum);
    }
    DispatchExtendedHook(ExternalModHookType::OnPlayDestroy, context, "OnPlayDestroy");
    if (mWorldGraphicsRuntime) {
        mWorldGraphicsRuntime->Reset(gPlayState);
    }
    for (auto& package : mPackages) {
        if (mPlayerResourcesRuntime) {
            mPlayerResourcesRuntime->OnPlayDestroy(package);
        }
        if (package.runtime.persistentStateDirty && RuntimeHasPersistentState(package.runtime)) {
            PersistRuntimeStateForPackage(package);
            package.runtime.persistentStateDirty = false;
        }
        ClearStatusEffects(package.runtime, gPlayState, false);
        ClearSurfState(package.runtime);
        package.runtime.activeAoEs.clear();
        package.runtime.activeStates.clear();
        package.runtime.activeFxHandles.clear();
        package.runtime.fxHandleByKey.clear();
        package.runtime.spellCooldownsById.clear();
        package.runtime.inventoryExtPages.clear();
        package.runtime.activeContainerProcesses.clear();
        package.runtime.activeNavPaths.clear();
        package.runtime.activeDynamicLights.clear();
        package.runtime.materialOverrides.clear();
        package.runtime.openUiScreens.clear();
        package.runtime.debugOverlayVisibility.clear();
        package.runtime.activeSceneProfileId.clear();
        package.runtime.activeRoomProfileId.clear();
        package.runtime.activePostFxPresetId.clear();
        package.runtime.activePostFxOwnerModId.clear();
        package.runtime.activePostFxDurationMs = 0;
        package.runtime.activePostFxRemainingMs = 0;
        package.runtime.activePostFxBlend = 1.0f;
        package.runtime.activeSkylightProfileId.clear();
        package.runtime.nextNavPathHandle = 1;
        package.runtime.nextDynamicLightHandle = 1;
        package.runtime.hasEffectImpactPosition = false;
        package.runtime.effectImpactPosX = 0.0f;
        package.runtime.effectImpactPosY = 0.0f;
        package.runtime.effectImpactPosZ = 0.0f;
        package.runtime.useProfileSpawnedShockwave = false;
        package.runtime.actorInstances.clear();
        package.runtime.nextActorHandle = 1;
        package.runtime.pendingSignals.clear();
        package.runtime.wasmTargetHandles.clear();
        package.runtime.wasmNextTargetHandle = 1;
        package.runtime.lastSceneSeen = -1;
        package.runtime.lastRoomSeen = -1;
        package.runtime.lastSkyboxSeen = -1;
        package.runtime.hasLastDayNight = false;
        package.runtime.lastIsNight = false;
        package.runtime.switchSnapshotInitialized = false;
        package.runtime.switchSnapshot.fill(0);
    }
    ClearAimSelectState(true);
    SyncExtraInventoryGrid();
    ApplyModItemAgeRequirementOverrides(mPackages);
    ApplyModItemIconOverrides(mPackages);
    ApplyModHookshotTextureOverrides(mPackages);
}
